// src/index.ts
import { Buffer } from "node:buffer";
import { relative } from "node:path";
import process from "node:process";
import { c, createLogger } from "@ntnyq/logger";
import jsBeautify from "js-beautify";
import PluginError from "plugin-error";
import through from "through2";
var rootDir = process.cwd();
var PLUGIN_NAME = "gulp-format-html";
var DEFAULT_OPTIONS = {
  indent_size: 2,
  inline: [],
  content_unformatted: ["pre", "textarea", "script"]
};
var logger = createLogger({ time: "HH:mm:ss" });
var beautifyHtml = jsBeautify.html;
var formatHTML = (options = {}) => {
  options = Object.assign({}, DEFAULT_OPTIONS, options);
  return through.obj((file, _enc, next) => {
    if (file.isNull()) return next(null, file);
    function transform(buffer, _, cb) {
      try {
        const contents = Buffer.from(
          beautifyHtml(buffer?.toString() ?? "", options)
        );
        if (next === cb) {
          file.contents = contents;
          return cb(null, file);
        }
        cb(null, contents);
        next(null, file);
      } catch (err) {
        const errorOptions = Object.assign({}, options, { fileName: file.path });
        const error = new PluginError(PLUGIN_NAME, err, errorOptions);
        if (next !== cb) {
          return next(error);
        }
        cb(error);
      }
    }
    if (file.isStream()) {
      file.contents = file.contents.pipe(through(transform));
    } else {
      if (options.verbose) {
        logger.info(
          `${c.yellow(PLUGIN_NAME)}: ${c.green(relative(rootDir, file.path))}`
        );
      }
      transform(file.contents, null, next);
    }
  });
};
var index_default = formatHTML;
export {
  index_default as default,
  formatHTML
};
